import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"Permissions & safety","description":"allow/ask/deny rules per tool and pattern, permission modes, the always-allow gotcha, external directories, and the bash sandbox.","frontmatter":{"title":"Permissions & safety","description":"allow/ask/deny rules per tool and pattern, permission modes, the always-allow gotcha, external directories, and the bash sandbox."},"headers":[],"relativePath":"using/permissions.md","filePath":"using/permissions.md"}'),o={name:"using/permissions.md"};function n(r,e,l,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<p>Nothing destructive happens quietly. Every tool call — reads, edits, shell commands, web fetches — is evaluated against permission rules before it runs, and the outcome is <code>allow</code>, <code>ask</code>, or <code>deny</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The permission system is <strong>guardrails, not isolation</strong>. It asks before it touches, but it is not a security boundary — a determined prompt injection is still a prompt injection. For true containment, run PrioriCode in a container or VM, and read the <a href="https://github.com/Prioritech-Indonesia-Optima/prioricode/blob/main/SECURITY.md" target="_blank" rel="noreferrer">threat model in SECURITY.md</a>.</p></div><h2 id="the-grammar" tabindex="-1">The grammar <a class="header-anchor" href="#the-grammar" aria-label="Permalink to &quot;The grammar&quot;">​</a></h2><p>Each permission corresponds to a tool — <code>read</code>, <code>edit</code>, <code>bash</code>, <code>glob</code>, <code>grep</code>, <code>list</code>, <code>task</code>, <code>webfetch</code>, <code>websearch</code>, <code>external_directory</code>, <code>todowrite</code>, <code>question</code>, <code>lsp</code>, <code>skill</code>, <code>doom_loop</code>, plus MCP tool names — and each one resolves to an action:</p><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th></tr></thead><tbody><tr><td><code>allow</code></td><td>Runs without asking.</td></tr><tr><td><code>ask</code></td><td>You approve or reject — per call.</td></tr><tr><td><code>deny</code></td><td>Refused; the model is told. A tool denied outright (<code>&quot;*&quot;: &quot;deny&quot;</code>) disappears from the agent&#39;s toolset entirely.</td></tr></tbody></table><p>Rules are pattern-based: the tool takes the <em>thing</em> it wants to touch (a file path, a command string, a URL) and matches it against glob patterns. <strong>Last match wins</strong>, so put your exceptions after your generalities. When no rule matches, the default is <code>ask</code>.</p><p>In <code>prioricode.json</code> (see <a href="./../configure/files.html">config files</a>):</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;permission&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;edit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// shorthand: every edit, always</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;*.env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ask&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// .env is sensitive — ask</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;*.env.example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;bash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;bun run *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tests are fine</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;git push*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ask&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;rm *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deny&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Patterns expand <code>~/</code> and <code>$HOME</code>. One-off overrides: the <code>tools</code> config map (<code>{ &quot;webfetch&quot;: false }</code> hides the tool) or the <code>PRIORICODE_PERMISSION</code> environment variable (a JSON ruleset merged over your file config).</p><h2 id="what-the-defaults-already-know" tabindex="-1">What the defaults already know <a class="header-anchor" href="#what-the-defaults-already-know" aria-label="Permalink to &quot;What the defaults already know&quot;">​</a></h2><p>Before your config is layered in, every agent starts from a baseline:</p><ul><li><strong><code>.env</code> files ask.</strong> Reading <code>*.env</code> needs your explicit yes; <code>*.env.example</code> is free. Secrets shouldn&#39;t leak into context by accident.</li><li><strong>Outside your project asks.</strong> Reads or writes aimed beyond the project directory trip the <code>external_directory</code> rule with a <code>&lt;dir&gt;/*</code> pattern. A few work areas are pre-allowed (PrioriCode&#39;s own temp/truncation dirs, skill directories, configured <a href="./../configure/files.html">references</a>); the shell is the same story — <code>bash</code> parses your command with tree-sitter and asks before letting <code>rm</code>/<code>mv</code>/<code>cp</code> reach outside the workspace.</li><li><strong>Loops ask.</strong> Three identical tool calls in a row triggers a <code>doom_loop</code> permission — &quot;are you sure, again?&quot; is sometimes all it takes to break a rut.</li><li><strong><code>question</code>, <code>plan_enter</code>, <code>plan_exit</code></strong> default to deny and are enabled per agent (<a href="./agents.html">agents</a>).</li></ul><h2 id="in-the-moment-the-permission-panel" tabindex="-1">In the moment: the permission panel <a class="header-anchor" href="#in-the-moment-the-permission-panel" aria-label="Permalink to &quot;In the moment: the permission panel&quot;">​</a></h2><p>When something asks, the session view shows the actual object: a syntax-highlighted diff for edits, the full command string for bash, the URL for fetches. Three choices:</p><ol><li><strong>Allow once</strong> — this call only.</li><li><strong>Allow always</strong> — a confirmation stage lists the rule it&#39;s adding (e.g. <code>git diff*</code>), and it holds <em>until PrioriCode is restarted</em>. Approve accordingly.</li><li><strong>Reject</strong> — and for subagent requests, rejection opens a text field: tell it what to do differently, and your words become the correction it receives.</li></ol><p><code>escape</code> rejects, <code>return</code> confirms, arrow keys (or <code>h</code>/<code>l</code>) select, and <code>ctrl+f</code> toggles fullscreen for the big diffs. Pending asks stack up in the footer as &quot;N Permissions&quot;.</p><h2 id="permission-modes-per-session" tabindex="-1">Permission modes (per session) <a class="header-anchor" href="#permission-modes-per-session" aria-label="Permalink to &quot;Permission modes (per session)&quot;">​</a></h2><p><code>/permission</code> (or the palette&#39;s &quot;Permission mode&quot;) sets the whole session&#39;s posture:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><code>default</code></td><td>Follow agent + project rules. The normal life.</td></tr><tr><td><code>ask-first</code></td><td>Edits and bash always confirm, whatever config says. Trust but verify.</td></tr><tr><td><code>always-allow</code></td><td>Skips confirmations — <strong>except destructive bash commands</strong>, which still ask. Yes, <code>rm -rf</code> keeps its manners.</td></tr></tbody></table><p><code>prioricode --auto</code> sets <code>always-allow</code> at launch (aliases <code>--yolo</code> and <code>--dangerously-skip-permissions</code> do the same). It&#39;s honest about what it does: the CLI help literally calls it dangerous. Use it for CI and one-shot batch work, not for &quot;I don&#39;t want to read&quot;.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Want less prompting without going full-send? Stay in <code>default</code> mode and give the repetitive things an explicit allow pattern — <code>&quot;bash&quot;: { &quot;bun run *&quot;: &quot;allow&quot; }</code> keeps approvals narrow, named, and reviewable. A session mode is a blunt object; patterns are the scalpel.</p></div><h2 id="sandboxing-bash" tabindex="-1">Sandboxing bash <a class="header-anchor" href="#sandboxing-bash" aria-label="Permalink to &quot;Sandboxing bash&quot;">​</a></h2><p>On macOS and Linux, <code>bashSandbox</code> wraps shell commands in an OS sandbox — macOS seatbelt (<code>sandbox-exec</code>), Linux bubblewrap (<code>bwrap</code>):</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;bashSandbox&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;best-effort&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;off&quot; (default) | &quot;best-effort&quot; | &quot;require&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;network&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deny&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// deny network to commands by default</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;writablePaths&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tmp/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// extra paths commands may write</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The filesystem becomes read-everywhere-but-write-here: your project, worktree, git dir, and package caches stay writable; everything else is read-only. <code>require</code> fails commands when the sandbox can&#39;t start (no silent fallbacks); <code>best-effort</code> falls back and says so. Windows doesn&#39;t support it, and PowerShell/cmd commands are never sandboxed. A nonzero exit inside the sandbox comes with a hint pointing at <code>writablePaths</code>/<code>network</code> — sandbox denials wear the same face as real errors.</p><h2 id="non-interactive-reality" tabindex="-1">Non-interactive reality <a class="header-anchor" href="#non-interactive-reality" aria-label="Permalink to &quot;Non-interactive reality&quot;">​</a></h2><p>In <code>prioricode run</code> (no TUI to ask), anything that would <code>ask</code> is <strong>rejected</strong> unless <code>--auto</code>. <code>question</code>/<code>plan_enter</code>/<code>plan_exit</code> are denied up front. If a script needs room to move, grant it in config before you launch it — CI should be boring on purpose. See <a href="./headless.html">headless</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./agents.html">Agents</a> — Per-agent permission profiles. <ul><li><a href="./../reference/config.html">Config reference</a> — <code>permission</code>, <code>bashSandbox</code>, <code>tools</code>, and every key.</li><li><a href="./../extending/hooks.html">Hooks</a> — Run your own gatekeeper script on every tool call.</li><li><a href="./../support/troubleshooting.html">Troubleshooting</a> — When a permission won&#39;t stick.</li></ul></li></ul>`,29)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
